<script setup lang="ts">
import { ref } from "vue";import{onLoad,onPullDownRefresh}from"@dcloudio/uni-app";import WareState from"@/shared/components/WareState.vue";import SessionTrigger from"@/shared/components/SessionTrigger.vue";import SessionDatePicker from"@/shared/components/SessionDatePicker.vue";import{bulkPurchaseApi,type BulkOrder}from"../../api/bulk-purchase.api";
const date=ref(new Date().toISOString().slice(0,10)),status=ref(-1),keyword=ref(""),rows=ref<BulkOrder[]>([]),loading=ref(true),error=ref(""),datePicker=ref(false),active=ref<BulkOrder|null>(null);const statuses=[[-1,"全部状态"],[10,"待签到"],[20,"待盘点"],[30,"待结算"],[40,"已结算"],[90,"已取消"]] as const;const statusName=(v:number)=>statuses.find(x=>x[0]===v)?.[1]||"未知";async function load(){loading.value=true;error.value="";try{rows.value=await bulkPurchaseApi.orders({roundNo:date.value,status:status.value,keyword:keyword.value.trim()})}catch(e){error.value=e instanceof Error?e.message:"集采订单加载失败"}finally{loading.value=false;uni.stopPullDownRefresh()}}onLoad(load);onPullDownRefresh(load);
</script>
<template><view class="page"><view class="filters"><input v-model="keyword" placeholder="供货单、货架或供应商" @confirm="load"/><SessionTrigger :value="date" @click="datePicker=true"/><picker :range="statuses.map(x=>x[1])" @change="status=statuses[Number($event.detail.value)][0];load()"><view class="status-trigger">{{statusName(status)}}<i/></view></picker></view><WareState v-if="loading" type="loading" title="正在加载集采订单"/><WareState v-else-if="error" type="error" title="集采订单加载失败" :description="error" action-label="重试" @action="load"/><WareState v-else-if="!rows.length" type="empty" title="暂无集采订单" description="当前场次没有符合条件的供货单"/><view v-else class="list"><view v-for="x in rows" :key="x.id" class="card" @click="active=x"><view class="head"><view><b>{{x.supplierName}}</b><text>{{x.orderNo}}</text></view><span :class="`s${x.status}`">{{statusName(x.status)}}</span></view><view class="product"><strong>{{x.secondName}}</strong><text>货架 {{x.shelfCode}}</text></view><view class="progress"><view><text>定采</text><b>{{x.confirmNum}}<small>枝</small></b></view><view><text>实际产出</text><b>{{x.actualNum}}<small>枝</small></b></view><view><text>标签</text><b>{{x.scannedLabelCount}}/{{x.scannedLabelCount+x.unscannedLabelCount}}</b></view></view><view class="foot"><text>{{x.roundNo}} · {{x.isDounan?'斗南':'非斗南'}}</text><text>查看详情 ›</text></view></view></view><view v-if="active" class="mask" @click="active=null"><view class="drawer" @click.stop><view class="handle"/><view class="drawer-head"><view><b>{{active.supplierName}}</b><text>{{active.orderNo}}</text></view><span>{{statusName(active.status)}}</span></view><view class="detail"><text>关联需求</text><b>{{active.demandNo}}</b><text>花材</text><b>{{active.secondName}}</b><text>集采货架</text><b>{{active.shelfCode}}</b><text>规格</text><b>{{active.specNum}}枝/扎</b><text>供应商报价量</text><b>{{active.totalSupplyNum}}枝</b><text>定采量</text><b>{{active.confirmNum}}枝</b><text>实际产出</text><b>{{active.actualNum}}枝</b><text>签到截止</text><b>{{active.checkInEndTime}}</b><text>签到时间</text><b>{{active.checkInTime||'未签到'}}</b><text>应结算数量</text><b>{{active.settleNum??'待盘点'}}{{active.settleNum==null?'':'枝'}}</b><text>结算金额</text><b>{{active.totalAmount==null?'待核算':`¥${Number(active.totalAmount).toFixed(2)}`}}</b></view><button @click="active=null">关闭</button></view></view><SessionDatePicker :visible="datePicker" :model-value="date" @close="datePicker=false" @confirm="date=$event;datePicker=false;load()"/></view></template>
<style scoped>.page{min-height:100vh;padding:18rpx;background:var(--wms-background)}.filters{display:grid;grid-template-columns:minmax(0,1fr) 210rpx 150rpx;gap:9rpx;margin-bottom:14rpx}.filters input,.status-trigger{box-sizing:border-box;height:62rpx;padding:0 13rpx;border:1rpx solid var(--wms-border);border-radius:8rpx;background:#fff;font-size:19rpx}.status-trigger{display:flex;align-items:center;justify-content:space-between;color:var(--wms-primary-700)}.status-trigger i{width:9rpx;height:9rpx;border-right:2rpx solid;border-bottom:2rpx solid;transform:rotate(45deg) translateY(-3rpx)}.list{display:flex;flex-direction:column;gap:12rpx}.card{padding:19rpx;border-radius:14rpx;background:#fff}.head,.product,.foot,.drawer-head{display:flex;align-items:center;justify-content:space-between}.head b,.head text{display:block}.head b{font-size:24rpx}.head text{margin-top:4rpx;color:var(--wms-text-secondary);font-size:17rpx}.head span,.drawer-head span{padding:5rpx 10rpx;border-radius:7rpx;background:var(--wms-surface-soft);color:var(--wms-primary-700);font-size:18rpx}.head .s10,.head .s20{background:#fff3dd;color:var(--wms-warning)}.head .s90{background:#eef1f0;color:var(--wms-text-secondary)}.product{margin-top:14rpx;padding-top:13rpx;border-top:1rpx solid var(--wms-border)}.product strong{font-size:22rpx}.product text{color:var(--wms-text-secondary);font-size:18rpx}.progress{display:grid;grid-template-columns:repeat(3,1fr);margin-top:14rpx;padding:14rpx 0;background:var(--wms-surface-page)}.progress view{text-align:center;border-right:1rpx solid var(--wms-border)}.progress view:last-child{border:0}.progress text,.progress b{display:block}.progress text{color:var(--wms-text-secondary);font-size:17rpx}.progress b{margin-top:4rpx;font-size:25rpx}.progress small{font-size:16rpx}.foot{margin-top:13rpx;color:var(--wms-text-secondary);font-size:17rpx}.foot text:last-child{color:var(--wms-primary-700)}.mask{position:fixed;z-index:80;inset:0;display:flex;align-items:flex-end;background:#0007}.drawer{box-sizing:border-box;width:100%;min-height:62vh;padding:14rpx 24rpx calc(24rpx + env(safe-area-inset-bottom));border-radius:24rpx 24rpx 0 0;background:#fff}.handle{width:66rpx;height:7rpx;margin:0 auto 20rpx;border-radius:7rpx;background:var(--wms-border)}.drawer-head b,.drawer-head text{display:block}.drawer-head b{font-size:27rpx}.drawer-head text{margin-top:4rpx;color:var(--wms-text-secondary);font-size:18rpx}.detail{display:grid;grid-template-columns:170rpx 1fr;gap:14rpx;margin-top:25rpx;font-size:20rpx}.detail text{color:var(--wms-text-secondary)}.detail b{text-align:right}.drawer button{position:absolute;right:24rpx;bottom:24rpx;left:24rpx;width:calc(100% - 48rpx);margin:0;border-radius:9rpx;background:var(--wms-primary-700);color:#fff}</style>
